import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"通义灵码术语表","description":"解释通义灵码为什么改名 Qoder CN、IDE 和插件不是一回事、三种会话模式差在哪。不教安装，不列价格。","frontmatter":{"title":"通义灵码术语表","description":"解释通义灵码为什么改名 Qoder CN、IDE 和插件不是一回事、三种会话模式差在哪。不教安装，不列价格。","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"zh/products/lingma/lingma-glossary.md","filePath":"zh/products/lingma/lingma-glossary.md","lastUpdated":1787107158000}'),d={name:"zh/products/lingma/lingma-glossary.md"};function n(s,t,i,l,g,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="通义灵码术语表" tabindex="-1">通义灵码术语表 <a class="header-anchor" href="#通义灵码术语表" aria-label="Permalink to &quot;通义灵码术语表&quot;">​</a></h1><p>不教操作，只解释「是什么 / 不是什么」。上手回 <a href="./lingma.html">教程</a>，选型回 <a href="./">学习地图</a>。</p><h2 id="通义灵码-qoder-cn" tabindex="-1">通义灵码 / Qoder CN <a class="header-anchor" href="#通义灵码-qoder-cn" aria-label="Permalink to &quot;通义灵码 / Qoder CN&quot;">​</a></h2><p><strong>是什么：</strong> 阿里云的智能编码助手。营销首页原文：「通义灵码是由阿里云提供的智能编码辅助工具，提供代码智能生成、智能问答、多文件修改、编程智能体等能力。」帮助中心把同一编码子产品定义为 Qoder CN 系列里「面向软件开发场景的核心子产品（原“通义灵码”）」。</p><p><strong>为什么改名：</strong> 官方说明写于 2026-05-20。系列覆盖编码、办公、终端、数字员工、云端 Agent。公共云「通义灵码」升级为 Qoder CN 之后，编码桌面应用现名 <strong>Qoder CN IDE</strong>，并继续提供 JetBrains 插件。</p><p><strong>在生态中的角色：</strong> 对位 Copilot / Cursor 这种「进编辑器干活」的产品，不是对位 ChatGPT 网页。</p><p>官方文档：<a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">什么是 Qoder CN</a>、<a href="https://help.aliyun.com/zh/lingma/introduction-of-lingma" target="_blank" rel="noreferrer">什么是 Qoder CN 系列</a>。</p><h2 id="qoder-cn-ide-lingma-ide" tabindex="-1">Qoder CN IDE / Lingma IDE <a class="header-anchor" href="#qoder-cn-ide-lingma-ide" aria-label="Permalink to &quot;Qoder CN IDE / Lingma IDE&quot;">​</a></h2><p><strong>是什么：</strong> 独立桌面 IDE，全面集成编码助手，<strong>无需再装插件</strong>。营销站下载页仍写 <strong>Lingma IDE</strong>；帮助中心和新品牌站写 <strong>Qoder CN IDE</strong>。</p><p><strong>为什么需要：</strong> 官方把迭代重心放到这套 IDE（以及 JetBrains 插件）。VS Code 插件更新放缓或已停止维护时，这是官方建议的替代入口。</p><p><strong>与插件的区别：</strong> 插件寄生在你已有的编辑器里；IDE 是另一个客户端。计费页写过升级路径：卸载原 Lingma IDE，再安装 Qoder CN IDE。</p><h2 id="ide-插件" tabindex="-1">IDE 插件 <a class="header-anchor" href="#ide-插件" aria-label="Permalink to &quot;IDE 插件&quot;">​</a></h2><p><strong>是什么：</strong> 装进 JetBrains IDEs、Visual Studio Code、Visual Studio 的扩展。市场 / 包名长期残留 <code>TONGYI Lingma</code>、<code>tongyi-lingma</code>。</p><p><strong>不是什么：</strong> 不是 Qoder CN CLI，也不是 QoderWork 桌面办公助手。</p><p><strong>VS Code 的特殊地位：</strong> 帮助中心仍教安装，同时宣布更新放缓；计费页写「停止演进」；docs.qoder.cn 写「已停止维护」；国际站更新日志写 discontinued。三份官方页不完全一致，正文按「可装、但不是现行主入口」处理。</p><h2 id="智能问答-文件编辑-智能体" tabindex="-1">智能问答 / 文件编辑 / 智能体 <a class="header-anchor" href="#智能问答-文件编辑-智能体" aria-label="Permalink to &quot;智能问答 / 文件编辑 / 智能体&quot;">​</a></h2><p>三种是<strong>同一会话窗口里的模式</strong>，不是三个产品。</p><table tabindex="0"><thead><tr><th>模式</th><th>是什么</th><th>为什么单独存在</th></tr></thead><tbody><tr><td>智能问答 Ask</td><td>只给方案，不改仓库</td><td>先搞懂，避免误改</td></tr><tr><td>文件编辑 Edit</td><td>在你给的上下文里改多文件，强调精确、更快</td><td>你已经知道改哪</td></tr><tr><td>智能体 Agent</td><td>自己拆任务、感知工程、用工具和终端</td><td>你只给目标</td></tr></tbody></table><p>官方强调一次会话里可切换，不必新建会话。文件编辑在 Lingma IDE / JetBrains 上不存在；Visual Studio 暂仅问答。详细操作见 <a href="./lingma-cookbook.html">Cookbook</a>。</p><h2 id="nes-行间建议预测" tabindex="-1">NES（行间建议预测） <a class="header-anchor" href="#nes-行间建议预测" aria-label="Permalink to &quot;NES（行间建议预测）&quot;">​</a></h2><p><strong>是什么：</strong> Next Edit Suggestion。根据完整代码上下文、已做修改和光标位置，预测<strong>下一处</strong>变更。</p><p><strong>不是什么：</strong> 不是普通的行间续写。续写补「下一行」；NES 预测「下一处要改的点」。帮助中心更新日志里，IDE 侧 NES 曾升级为 <strong>NEXT</strong>。</p><p>官方文档：<a href="https://help.aliyun.com/zh/lingma/next-edit-suggestion" target="_blank" rel="noreferrer">行间建议预测</a>。</p><h2 id="工程自动感知-记忆感知" tabindex="-1">工程自动感知 / 记忆感知 <a class="header-anchor" href="#工程自动感知-记忆感知" aria-label="Permalink to &quot;工程自动感知 / 记忆感知&quot;">​</a></h2><p><strong>工程自动感知：</strong> 按任务描述感知框架、技术栈、相关文件、报错，不必手动把整个仓库贴进对话框。</p><p><strong>记忆感知：</strong> 对话过程中积累针对个人、工程、问题的记忆，并自动整理。官方单独成页：<a href="https://help.aliyun.com/zh/lingma/memory" target="_blank" rel="noreferrer">记忆</a>。</p><p>这两项解释的是「为什么打开相关文件、连续对话会越来越准」，不是「模型已经训练了你的私有仓库」。本站不写模型内部机制，见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>。</p><h2 id="quest-repowiki-subagent-专家团" tabindex="-1">Quest / RepoWiki / Subagent / 专家团 <a class="header-anchor" href="#quest-repowiki-subagent-专家团" aria-label="Permalink to &quot;Quest / RepoWiki / Subagent / 专家团&quot;">​</a></h2><p>帮助中心在「什么是 Qoder CN」里把它们列为 IDE 侧升级能力：</p><ul><li><strong>Quest 2.0</strong>：复杂研发任务自动拆成可执行步骤。</li><li><strong>RepoWiki</strong>：工程级知识库。</li><li><strong>Subagent</strong>：子智能体。</li><li><strong>专家团</strong>：面向前后端、数据库、运维、测试等的专家智能体。</li></ul><p>官方写：RepoWiki、Quest、Subagent 等核心能力按量抵扣 Credits、不限次数。本目录不把它们拆成独立教程——密度在产品介绍页，操作细节以 <a href="https://docs.qoder.cn/" target="_blank" rel="noreferrer">docs.qoder.cn</a> 为准。</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p><strong>是什么：</strong> 2026-05-20 起订阅席位引入的用量单位。超额可买资源包。全家桶个人版 Credits 可跨 IDE / JetBrains / QoderWork / CLI 等共享（完成账号升级后）。</p><p><strong>不是什么：</strong> 不是「免费就永远无限」。个人体验版官方写的是有限体验额度和 2 周试用。具体数字只看 <a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">计费说明</a>，不要背旧博客。</p><h2 id="不是什么" tabindex="-1">不是什么 <a class="header-anchor" href="#不是什么" aria-label="Permalink to &quot;不是什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>实际是</th><th>本站</th></tr></thead><tbody><tr><td><strong>通义千问</strong></td><td>通用 AI 助手（<a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a>）</td><td>家族图一行，#83</td></tr><tr><td><strong>百炼</strong></td><td>大模型服务 / Agent 开发平台</td><td>家族图一行，#85</td></tr><tr><td><strong>Qoder CN CLI</strong></td><td>终端子产品</td><td>家族图一行</td></tr><tr><td><strong>QoderWork CN</strong></td><td>办公桌面助手</td><td>家族图一行</td></tr><tr><td><strong>QoderWake CN</strong></td><td>数字员工</td><td>家族图一行</td></tr><tr><td><strong>Cloud Agents</strong></td><td>云端托管 Agent 平台</td><td>家族图一行</td></tr><tr><td><strong>淘宝 / ECS / 支付</strong></td><td>非 AI 产品</td><td>非本站</td></tr><tr><td>「通义灵码 = 通义千问的 IDE 皮肤」</td><td>错误说法</td><td>两个产品</td></tr><tr><td>「只有 VS Code 插件」</td><td>错误说法</td><td>官方主推 IDE + JetBrains</td></tr></tbody></table><h2 id="已退役或已改名" tabindex="-1">已退役或已改名 <a class="header-anchor" href="#已退役或已改名" aria-label="Permalink to &quot;已退役或已改名&quot;">​</a></h2><table tabindex="0"><thead><tr><th>旧说法</th><th>现状</th></tr></thead><tbody><tr><td>智能编码助手通义灵码（Lingma）</td><td>2026-05-20 起系列名 Qoder CN</td></tr><tr><td>Lingma IDE</td><td>现名 Qoder CN IDE；旧安装包需按官方路径卸载再装</td></tr><tr><td>TONGYI Lingma 插件展示名</td><td>帮助中心改为 Qoder CN；市场 ID 仍是 <code>Alibaba-Cloud.tongyi-lingma</code></td></tr><tr><td>个人专业版限时免费</td><td>2026-05-20 18:00 结束，限免用户转个人社区 / 体验档</td></tr></tbody></table><p>选哪个入口，看 <a href="./">学习地图</a> 的决策树。</p>',39)])])}const f=r(d,[["render",n]]);export{b as __pageData,f as default};
